package com.bobbuy.service;
import com.bobbuy.model.*;
import com.bobbuy.repository.*;
import com.bobbuy.test.PriceDocumentFixtures;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class ReferenceQuoteTest {
 final ProductPriceAdjustmentRepository docs=PriceDocumentFixtures.repository();
 final ReferenceQuoteRevisionRepository history=mock(ReferenceQuoteRevisionRepository.class);
 final RecommendationPostRepository posts=mock(RecommendationPostRepository.class);
 final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
 final ReferenceQuoteService service=new ReferenceQuoteService(history,json,mock(RecommendationItemRepository.class),posts,docs);
 RecommendationItem item(){var i=new RecommendationItem();i.id=1L;i.postId=2L;i.productId="p";i.itemNumber="001";i.name="Synthetic";i.referencePrice=new BigDecimal("80");i.originalPrice=new BigDecimal("100");i.priceUnit="1 pack";i.sourcePrice=new RecommendationItem.SourcePrice(i.referencePrice,i.originalPrice,null,i.priceUnit,null,LocalDate.of(2099,1,1));i.referenceContext=new ReferenceOfferContext("SYNTHETIC","COSTCO_WAREHOUSE","pack","message","https://www.costco.co.jp/synthetic",null,null,false,null,true);var p=new RecommendationPost();p.id=2L;p.merchantId=10L;when(posts.findAllById(List.of(2L))).thenReturn(List.of(p));return i;}
 ProductPriceAdjustment document(ProductPriceAdjustment.Type type,String amount,ProductPriceAdjustment.Status status,boolean linked){var d=new ProductPriceAdjustment();d.merchantId=10L;d.channel="COSTCO_WAREHOUSE";d.currency="JPY";d.type=type;d.status=status;d.documentNumber="TEST-"+amount;d.createdAt=Instant.parse("2020-01-01T00:00:00Z");d.startsAt=d.createdAt;d.approvedAt=d.createdAt;d.endsAt=type==ProductPriceAdjustment.Type.PERMANENT?null:Instant.parse("2099-01-01T00:00:00Z");d.sourceNote="Synthetic supplier promotion reason";var line=new ProductPriceAdjustmentLine();line.document=d;line.productId="p";line.unit="1 pack";line.amount=new BigDecimal(amount);line.beforeAmount=new BigDecimal("100");line.referenceItemId=linked?1L:null;d.lines.add(line);return docs.saveAndFlush(d);}
 @Test void sourceDateInheritanceRemainsAnImportValidationRule(){var c=new ReferenceOfferContext("s","COSTCO_ONLINE","v","m","https://www.costco.co.jp/source",LocalDate.of(2026,11,1),LocalDate.of(2026,11,30),true,"Explicit applicable source period",true);var window=ReferenceOfferWindow.resolve(LocalDate.of(2026,11,5),null,c);assertThat(window.start()).isEqualTo(LocalDate.of(2026,11,5));assertThat(window.end()).isEqualTo(LocalDate.of(2026,11,30));assertThat(ReferenceOfferWindow.resolve(null,null,null).complete()).isFalse();}
 @Test void incompleteSourceBecomesDraftDocumentAndNeverInventsStartOrReasonApproval(){var i=item();service.snapshot(i,10L);var d=docs.forReferenceItem(1L).get(0);assertThat(d.status).isEqualTo(ProductPriceAdjustment.Status.DRAFT);assertThat(d.startsAt).isNull();assertThat(d.endsAt).isNotNull();assertThat(d.sourceNote).isNotBlank();assertThat(d.evidence.get("reviewRequired")).isEqualTo(true);assertThat(d.line("p").amount).isEqualByComparingTo("80");}
 @Test void unitOnlySourceIsRetainedWithoutInventingPriceOrPeriod(){var i=item();i.sourcePrice=new RecommendationItem.SourcePrice(null,null,null,"per synthetic pack",null,null);service.snapshot(i,10L);var d=docs.forReferenceItem(1L).get(0);assertThat(d.status).isEqualTo(ProductPriceAdjustment.Status.DRAFT);assertThat(d.line("p").amount).isNull();assertThat(d.line("p").unit).isEqualTo("per synthetic pack");assertThat(d.startsAt).isNull();assertThat(d.endsAt).isNull();}
 @Test void sourceReplayDoesNotDuplicateAndChangedSourceRetainsPreviousDocument(){var i=item();service.snapshot(i,10L);service.snapshot(i,10L);assertThat(docs.forReferenceItem(1L)).hasSize(1);i.sourcePrice=new RecommendationItem.SourcePrice(new BigDecimal("70"),new BigDecimal("100"),null,"1 pack",null,LocalDate.of(2099,1,1));service.snapshot(i,10L);assertThat(docs.forReferenceItem(1L)).hasSize(2);assertThat(docs.forReferenceItem(1L).get(1).line("p").amount).isEqualByComparingTo("80");}
 @Test void noDocumentCannotFallBackToItemSourceDatesOrPrices(){var i=item();service.decorate(List.of(i),true);assertThat(i.referencePrice).isNull();assertThat(i.priceChange).isNull();assertThat(i.referenceQuote.state()).isEqualTo("UNKNOWN");}
 @Test void approvedPromotionProducesEffectiveReferenceAndRedactsPrivateSourceIdentity(){var i=item();document(ProductPriceAdjustment.Type.PROMOTION,"80",ProductPriceAdjustment.Status.APPROVED,true);service.decorate(List.of(i),true);assertThat(i.referencePrice).isEqualByComparingTo("80");assertThat(i.originalPrice).isEqualByComparingTo("100");assertThat(i.priceChange.promotion()).isTrue();assertThat(i.referenceContext.sourceMessageKey()).isNull();assertThat(i.referenceContext.sourceUrl()).isEqualTo("https://www.costco.co.jp/synthetic");}
 @Test void draftAndCancelledSourcesDoNotBecomeEffectivePromotions(){for(var state:List.of(ProductPriceAdjustment.Status.DRAFT,ProductPriceAdjustment.Status.CANCELLED)){var i=item();var d=document(ProductPriceAdjustment.Type.PROMOTION,"80",state,true);service.decorate(List.of(i),true);assertThat(i.priceChange).isNull();assertThat(i.referencePrice).isNull();assertThat(i.originalPrice).isNull();d.lines.get(0).referenceItemId=null;}}
 @Test void permanentReferenceChangeUpdatesRegularWithoutPromotionAndNeverBorrowsStorefront(){var i=item();document(ProductPriceAdjustment.Type.PROMOTION,"80",ProductPriceAdjustment.Status.DRAFT,true);document(ProductPriceAdjustment.Type.PERMANENT,"90",ProductPriceAdjustment.Status.APPROVED,false);var actual=document(ProductPriceAdjustment.Type.PROMOTION,"1",ProductPriceAdjustment.Status.APPROVED,false);actual.channel="STOREFRONT";service.decorate(List.of(i),true);assertThat(i.referencePrice).isEqualByComparingTo("90");assertThat(i.priceChange.type()).isEqualTo("PERMANENT");assertThat(i.priceChange.promotion()).isFalse();assertThat(i.originalPrice).isNull();}
 @Test void wrongMerchantAndSourceItemIdentityAreRejected(){var i=item();var d=document(ProductPriceAdjustment.Type.PROMOTION,"80",ProductPriceAdjustment.Status.APPROVED,true);d.merchantId=99L;service.decorate(List.of(i),true);assertThat(i.referencePrice).isNull();d.merchantId=10L;d.evidence.put("sourceItemNumber","DIFFERENT");service.decorate(List.of(i),true);assertThat(i.referencePrice).isNull();}
 @Test void manualReferenceDocumentNeedsNoRecommendationAndPreservesScope(){var p=new Product();p.setId("p");p.setMerchantId(10L);p.setItemNumber("001");p.setCurrency("JPY");var d=document(ProductPriceAdjustment.Type.PERMANENT,"90",ProductPriceAdjustment.Status.APPROVED,false);var prices=service.currentPrices(List.of(p)).get("p");assertThat(prices).hasSize(1);assertThat(prices.get(0).amount()).isEqualByComparingTo("90");assertThat(prices.get(0).regularAmount()).isEqualByComparingTo("90");assertThat(prices.get(0).promotion()).isFalse();d.channel="STOREFRONT";assertThat(service.currentPrices(List.of(p)).get("p")).isEmpty();d.channel="COSTCO_WAREHOUSE";d.merchantId=99L;assertThat(service.currentPrices(List.of(p)).get("p")).isEmpty();d.merchantId=10L;d.evidence.put("sourceItemNumber","other");assertThat(service.currentPrices(List.of(p)).get("p")).isEmpty();}
}
